import React, { useRef, useEffect } from 'react';
import { motion, useScroll, useTransform, useInView } from 'framer-motion';
import PageHero from '../components/ui/PageHero';
import './InnerPages.css';

const techs = [
  {
    number: '01',
    title: 'Intelligence Artificielle',
    subtitle: 'MBUX & PCM Neural',
    desc: 'Les systèmes MBUX et PCM intègrent des réseaux neuronaux qui cartographient vos habitudes de conduite pour une expérience entièrement personnalisée, évoluant à chaque trajet.',
    stat: '98%',
    statLabel: 'Précision prédictive',
  },
  {
    number: '02',
    title: 'Sécurité Prédictive',
    subtitle: 'Sensor Fusion 360°',
    desc: 'La fusion radar, LiDAR et caméras haute résolution crée une conscience situationnelle totale, anticipant les dangers à 250 mètres avec une réactivité de 2 millisecondes.',
    stat: '250m',
    statLabel: 'Portée de détection',
  },
  {
    number: '03',
    title: 'Architecture 800V',
    subtitle: 'Haute Tension Porsche',
    desc: 'La plateforme haute tension propriétaire permet une recharge 0→80% en moins de 20 minutes, offrant une densité énergétique inégalée sans compromis sur la longévité.',
    stat: '20min',
    statLabel: 'Charge complète',
  },
  {
    number: '04',
    title: 'Acoustique Adaptative',
    subtitle: 'Burmester & Bose',
    desc: "Les systèmes Burmester 4D et Bose Surround cartographient l'acoustique de l'habitacle en temps réel, ajustant dynamiquement l'égalisation selon la vitesse et le silence ambiant.",
    stat: '1.500W',
    statLabel: 'Puissance sonore',
  },
  {
    number: '05',
    title: 'Connectivité OTA',
    subtitle: 'Over-The-Air Evolution',
    desc: "Les mises à jour sans fil enrichissent votre véhicule de nouvelles fonctionnalités, optimisations de performance et correctifs de sécurité — sans immobilisation, sans atelier.",
    stat: '∞',
    statLabel: 'Évolutions continues',
  },
  {
    number: '06',
    title: 'Aérodynamique Active',
    subtitle: 'Dynamic Airflow Control',
    desc: "Les spoilers adaptatifs, diffuseurs actifs et volets de refroidissement modulants s'orchestrent en 12 millisecondes selon la vitesse, le mode de conduite et la thermique moteur.",
    stat: '0.19cd',
    statLabel: 'Cx record homologué',
  },
];

function TechCard({ tech, index }) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: '-80px' });

  return (
    <motion.div
      ref={ref}
      className="tech-card-v2"
      initial={{ opacity: 0, y: 60 }}
      animate={isInView ? { opacity: 1, y: 0 } : {}}
      transition={{ duration: 0.9, delay: (index % 3) * 0.12, ease: [0.22, 1, 0.36, 1] }}
    >
      <div className="tech-card-v2__header">
        <span className="tech-card-v2__number">{tech.number}</span>
        <div className="tech-card-v2__line" />
      </div>

      <div className="tech-card-v2__body">
        <span className="tech-card-v2__subtitle">{tech.subtitle}</span>
        <h3 className="tech-card-v2__title">{tech.title}</h3>
        <p className="tech-card-v2__desc">{tech.desc}</p>
      </div>

      <div className="tech-card-v2__footer">
        <div className="tech-card-v2__stat">
          <strong>{tech.stat}</strong>
          <span>{tech.statLabel}</span>
        </div>
        <div className="tech-card-v2__arrow">→</div>
      </div>

      <div className="tech-card-v2__border-anim" />
    </motion.div>
  );
}

export default function Technology() {
  const containerRef = useRef(null);
  const { scrollYProgress } = useScroll({ target: containerRef, offset: ['start end', 'end start'] });
  const lineHeight = useTransform(scrollYProgress, [0, 1], ['0%', '100%']);

  return (
    <main className="page-wrapper" ref={containerRef}>
      <PageHero
        label="Innovation"
        title="Technologie & Innovations"
        subtitle="À la pointe de l'ingénierie automobile mondiale."
        backgroundImage="/images/banner3.png"
      />

      {/* INTRO */}
      <section className="inner-section container">
        <motion.div
          className="tech-intro-v2"
          initial={{ opacity: 0, y: 40 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 1, ease: [0.22, 1, 0.36, 1] }}
        >
          <span className="section-label">Ingénierie Supérieure</span>
          <h2 className="inner-h2">
            Six disciplines,
            <br />
            <em>une seule obsession</em>
          </h2>
          <p className="inner-p" style={{ maxWidth: 560 }}>
            Chaque technologie embarquée dans nos véhicules résulte d'années
            de recherche et de validation. Aucun compromis sur la maîtrise.
          </p>
        </motion.div>

        {/* VERTICAL PROGRESS LINE */}
        <div className="tech-progress-line">
          <motion.div className="tech-progress-line__fill" style={{ height: lineHeight }} />
        </div>

        {/* GRID */}
        <div className="tech-grid-v2">
          {techs.map((t, i) => (
            <TechCard key={t.number} tech={t} index={i} />
          ))}
        </div>
      </section>
    </main>
  );
}
